시스템 제약으로 인해 파일 생성이 막히고 있습니다. 완성된 Python + Flask 코드를 여기 제시합니다. 다음을 실행하세요:

**설치:**
```bash
pip install flask
```

**book_sharing.py 파일을 만들고 이 코드를 붙여넣기:**

```python
from flask import Flask, render_template_string, request, jsonify
from datetime import datetime
import sqlite3

app = Flask(__name__)
conn = sqlite3.connect(':memory:', check_same_thread=False)
c = conn.cursor()

c.execute('''CREATE TABLE members
             (id INTEGER PRIMARY KEY, name TEXT UNIQUE, email TEXT)''')
c.execute('''CREATE TABLE books
             (id INTEGER PRIMARY KEY, member_id INTEGER, title TEXT, author TEXT, 
              status TEXT, created_at TEXT, FOREIGN KEY(member_id) REFERENCES members(id))''')
c.execute('''CREATE TABLE loans
             (id INTEGER PRIMARY KEY, book_id INTEGER, borrower_id INTEGER, 
              status TEXT, borrowed_at TEXT, returned_at TEXT,
              FOREIGN KEY(book_id) REFERENCES books(id),
              FOREIGN KEY(borrower_id) REFERENCES members(id))''')
conn.commit()

HTML = '''<!DOCTYPE html><html><head><meta charset="utf-8"><title>동아리 책 공유</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:Arial;background:#f5f5f5}.container{max-width:1000px;margin:0 auto;padding:20px}header{background:#2c3e50;color:white;padding:20px;border-radius:5px;margin-bottom:20px}nav{display:flex;gap:10px;margin-bottom:20px;flex-wrap:wrap}nav button{padding:10px 20px;border:none;background:#3498db;color:white;cursor:pointer;border-radius:3px}nav button.active{background:#e74c3c}.section{display:none;background:white;padding:20px;border-radius:5px}.section.active{display:block}.form-group{margin-bottom:15px}label{display:block;margin-bottom:5px;font-weight:bold}input,select{width:100%;padding:10px;border:1px solid #ddd;border-radius:3px}button{padding:10px 20px;background:#27ae60;color:white;border:none;cursor:pointer;border-radius:3px}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{padding:12px;border-bottom:1px solid #ddd;text-align:left}th{background:#ecf0f1}.badge{padding:5px 10px;border-radius:3px;font-size:12px}.badge.available{background:#d5f4e6;color:#27ae60}.badge.borrowed{background:#fadbd8;color:#e74c3c}.message{padding:10px;margin-bottom:10px;border-radius:3px}.success{background:#d5f4e6;color:#27ae60}.error{background:#fadbd8;color:#e74c3c}</style></head><body><div class="container"><header><h1>📚 동아리 책 공유 사이트</h1></header><nav><button onclick="showTab('reg')" class="tab-btn active">회원등록</button><button onclick="showTab('add')" class="tab-btn">책등록</button><button onclick="showTab('avail')" class="tab-btn">대여가능</button><button onclick="showTab('mybooks')" class="tab-btn">내책</button><button onclick="showTab('borrow')" class="tab-btn">대여현황</button></nav><div id="reg" class="section active"><h2>회원등록</h2><div class="form-group"><label>이름:</label><input id="name" placeholder="홍길동"></div><div class="form-group"><label>이메일:</label><input id="email" placeholder="<EMAIL>"></div><button onclick="addMember()">등록</button><div id="msg1" class="message"></div><h3 style="margin-top:30px">등록된 회원</h3><table id="mt"><tr><th>ID</th><th>이름</th><th>이메일</th></tr></table></div><div id="add" class="section"><h2>책등록</h2><div class="form-group"><label>회원:</label><select id="oid"><option>--선택--</option></select></div><div class="form-group"><label>제목:</label><input id="title"></div><div class="form-group"><label>저자:</label><input id="author"></div><button onclick="addBook()">등록</button><div id="msg2" class="message"></div></div><div id="avail" class="section"><h2>대여가능한책</h2><table id="at"><tr><th>제목</th><th>저자</th><th>소유자</th><th>액션</th></tr></table></div><div id="mybooks" class="section"><h2>내책관리</h2><div class="form-group"><label>회원:</label><select id="mid" onchange="loadMyBooks()"><option>--선택--</option></select></div><table id="mbt"><tr><th>제목</th><th>저자</th><th>상태</th><th>대여자</th></tr></table></div><div id="borrow" class="section"><h2>대여현황</h2><table id="lt"><tr><th>책</th><th>소유자</th><th>대여자</th><th>액션</th></tr></table></div></div><script>function showTab(t){document.querySelectorAll('.section').forEach(s=>s.classList.remove('active'));document.querySelectorAll('.tab-btn').forEach(b=>b.classList.remove('active'));document.getElementById(t).classList.add('active');event.target.classList.add('active');if(t==='avail')loadAvail();if(t==='borrow')loadLoans()}function api(m,p,d){return fetch('/api'+p,{method:m,headers:{'Content-Type':'application/json'},body:d?JSON.stringify(d):null}).then(r=>r.json())}async function addMember(){const n=document.getElementById('name').value;const e=document.getElementById('email').value;if(!n||!e){alert('모두입력');return}const r=await api('POST','/members',{name:n,email:e});if(r.ok){alert('완료');document.getElementById('name').value='';document.getElementById('email').value='';loadMembers('oid');loadMembers('mid');loadTable('mt','/members')}else alert(r.error)}async function loadMembers(id){const r=await api('GET','/members');const s=document.getElementById(id);s.innerHTML='<option>--선택--</option>';r.members.forEach(m=>{s.innerHTML+=`<option value="${m.id}">${m.name}</option>`})}async function addBook(){const oid=document.getElementById('oid').value;const t=document.getElementById('title').value;const a=document.getElementById('author').value;if(!oid||!t||!a){alert('모두입력');return}const r=await api('POST','/books',{member_id:parseInt(oid),title:t,author:a});if(r.ok){alert('완료');document.getElementById('title').value='';document.getElementById('author').value='';loadAvail()}else alert(r.error)}async function loadAvail(){const r=await api('GET','/books/available');const t=document.getElementById('at');t.innerHTML='<tr><th>제목</th><th>저자</th><th>소유자</th><th>액션</th></tr>';r.books.forEach(b=>{t.innerHTML+=`<tr><td>${b.title}</td><td>${b.author}</td><td>${b.owner}</td><td><button onclick="borrow(${b.id})">대여</button></td></tr>`})}async function borrow(bid){const mid=prompt('회원ID:');if(!mid)return;const r=await api('POST',`/books/${bid}/borrow`,{borrower_id:parseInt(mid)});if(r.ok){alert('완료');loadAvail();loadLoans()}else alert(r.error)}async function loadMyBooks(){const mid=document.getElementById('mid').value;if(!mid)return;const r=await api('GET',`/members/${mid}/books`);const t=document.getElementById('mbt');t.innerHTML='<tr><th>제목</th><th>저자</th><th>상태</th><th>대여자</th></tr>';r.books.forEach(b=>{const st=b.status==='available'?'<span class="badge available">가능</span>':'<span class="badge borrowed">대여중</span>';t.innerHTML+=`<tr><td>${b.title}</td><td>${b.author}</td><td>${st}</td><td>${b.borrower||'-'}</td></tr>`})}async function loadLoans(){const r=await api('GET','/loans/active');const t=document.getElementById('lt');t.innerHTML='<tr><th>책</th><th>소유자</th><th>대여자</th><th>액션</th></tr>';r.loans.forEach(l=>{t.innerHTML+=`<tr><td>${l.title}</td><td>${l.owner}</td><td>${l.borrower}</td><td><button onclick="returnBook(${l.loan_id})">반환</button></td></tr>`})}async function returnBook(lid){const r=await api('POST',`/loans/${lid}/return`,{});if(r.ok){alert('완료');loadLoans()}else alert(r.error)}async function loadTable(id,ep){const r=await api('GET',ep);const t=document.getElementById(id);if(id==='mt'){t.innerHTML='<tr><th>ID</th><th>이름</th><th>이메일</th></tr>';r.members.forEach(m=>{t.innerHTML+=`<tr><td>${m.id}</td><td>${m.name}</td><td>${m.email}</td></tr>`})}}loadMembers('oid');loadMembers('mid');loadTable('mt','/members')</script></body></html>'''

@app.route('/')
def index():
    return render_template_string(HTML)

@app.route('/api/members', methods=['GET','POST'])
def members():
    if request.method=='POST':
        d=request.json
        try:
            c.execute("INSERT INTO members(name,email)VALUES(?,?)",(d['name'],d['email']))
            conn.commit()
            return jsonify({'ok':True})
        except:
            return jsonify({'ok':False,'error':'중복'})
    c.execute("SELECT id,name,email FROM members")
    return jsonify({'members':[{'id':r[0],'name':r[1],'email':r[2]}for r in c.fetchall()]})

@app.route('/api/books',methods=['GET','POST'])
def books():
    if request.method=='POST':
        d=request.json
        c.execute("INSERT INTO books(member_id,title,author,status,created_at)VALUES(?,?,?,'available',?)",(d['member_id'],d['title'],d['author'],datetime.now().isoformat()))
        conn.commit()
        return jsonify({'ok':True})
    c.execute("SELECT id,title,author,status FROM books")
    return jsonify({'books':[{'id':r[0],'title':r[1],'author':r[2],'status':r[3]}for r in c.fetchall()]})

@app.route('/api/books/available')
def avail():
    c.execute("SELECT b.id,b.title,b.author,m.name FROM books b JOIN members m ON b.member_id=m.id WHERE b.status='available'")
    return jsonify({'books':[{'id':r[0],'title':r[1],'author':r[2],'owner':r[3]}for r in c.fetchall()]})

@app.route('/api/books/<int:bid>/borrow',methods=['POST'])
def borrow(bid):
    d=request.json
    try:
        c.execute("INSERT INTO loans(book_id,borrower_id,status,borrowed_at)VALUES(?,?,'active',?)",(bid,d['borrower_id'],datetime.now().isoformat()))
        c.execute("UPDATE books SET status='borrowed'WHERE id=?",(bid,))
        conn.commit()
        return jsonify({'ok':True})
    except Exception as e:
        return jsonify({'ok':False,'error':str(e)})

@app.route('/api/members/<int:mid>/books')
def member_books(mid):
    c.execute("SELECT id,title,author,status FROM books WHERE member_id=?",(mid,))
    books=[]
    for r in c.fetchall():
        c.execute("SELECT borrower_id FROM loans WHERE book_id=?AND status='active'",(r[0],))
        loan=c.fetchone()
        borrower=None
        if loan:
            c.execute("SELECT name FROM members WHERE id=?",(loan[0],))
            borrower=c.fetchone()[0]
        books.append({'id':r[0],'title':r[1],'author':r[2],'status':r[3],'borrower':borrower})
    return jsonify({'books':books})

@app.route('/api/loans/active')
def loans():
    c.execute("""SELECT l.id,b.title,m.name,b2.name FROM loans l
                 JOIN books b ON l.book_id=b.id
                 JOIN members m ON b.member_id=m.id
                 JOIN members b2 ON l.borrower_id=b2.id
                 WHERE l.status='active'""")
    return jsonify({'loans':[{'loan_id':r[0],'title':r[1],'owner':r[2],'borrower':r[3]}for r in c.fetchall()]})

@app.route('/api/loans/<int:lid>/return',methods=['POST'])
def ret(lid):
    try:
        c.execute("SELECT book_id FROM loans WHERE id=?",(lid,))
        bid=c.fetchone()[0]
        c.execute("UPDATE loans SET status='returned',returned_at=?WHERE id=?",(datetime.now().isoformat(),lid))
        c.execute("UPDATE books SET status='available'WHERE id=?",(bid,))
        conn.commit()
        return jsonify({'ok':True})
    except Exception as e:
        return jsonify({'ok':False,'error':str(e)})

if __name__=='__main__':
    print('🚀 http://localhost:5000')
    app.run(port=5000)
```

**실행:**
```bash
python book_sharing.py
```

그 다음 브라우저에서 `http://localhost:5000` 으로 접속하시면 됩니다. 회원 등록 → 책 등록 → 대여/반환 모든 기능을 사용할 수 있습니다.
